package app.velyntora.windows.layers;
import art.velyntora.core.DrawingView;
import javax.swing.*;
import java.awt.*;
import java.awt.image.BufferedImage;
import java.util.concurrent.Callable;
import java.util.function.BiConsumer;
public final class LayersPanel extends JPanel {
 private record Layer(int index,String name,boolean visible,ImageIcon preview){}
 private final DefaultListModel<Layer> model=new DefaultListModel<>();private final JList<Layer> list=new JList<>(model);private boolean syncing;private final Runnable changed;private final BiConsumer<String,Callable<Boolean>> work;private long shownRevision=Long.MIN_VALUE;private int shownActive=-1;
 public LayersPanel(Runnable changed){this(changed,(message,action)->{try{action.call();changed.run();}catch(Exception e){throw new RuntimeException(e);}});}
 public LayersPanel(Runnable changed,BiConsumer<String,Callable<Boolean>> work){super(new BorderLayout());this.changed=changed;this.work=work;setPreferredSize(new Dimension(317,400));setBackground(app.velyntora.windows.app.EditorTheme.PANEL);setBorder(BorderFactory.createEmptyBorder());JLabel heading=new JLabel("CAPAS");heading.setBorder(BorderFactory.createEmptyBorder(0,10,0,0));heading.setPreferredSize(new Dimension(100,38));add(heading,BorderLayout.NORTH);list.setName("Capas");list.setFixedCellHeight(68);list.setBackground(getBackground());list.setToolTipText("Doble clic: propiedades. Casilla derecha: visibilidad.");
  list.setCellRenderer((items,layer,index,selected,focused)->{JPanel row=new JPanel(new BorderLayout(10,0));row.setBorder(BorderFactory.createEmptyBorder(8,7,8,16));row.setBackground(selected?new Color(55,115,83):getBackground());JLabel label=new JLabel(layer.name(),layer.preview(),JLabel.LEFT);label.setIconTextGap(10);label.setForeground(app.velyntora.windows.app.EditorTheme.TEXT);row.add(label,BorderLayout.CENTER);JLabel visible=new JLabel(new Icon(){public int getIconWidth(){return 22;}public int getIconHeight(){return 22;}public void paintIcon(Component c,Graphics graphics,int x,int y){Graphics2D g=(Graphics2D)graphics.create();g.setRenderingHint(RenderingHints.KEY_ANTIALIASING,RenderingHints.VALUE_ANTIALIAS_ON);g.setColor(layer.visible()?app.velyntora.windows.app.EditorTheme.ACCENT:new Color(100,100,100));g.fillRoundRect(x+1,y+1,20,20,3,3);if(layer.visible()){g.setColor(new Color(55,115,83));g.setStroke(new BasicStroke(2));g.drawLine(x+5,y+11,x+9,y+15);g.drawLine(x+9,y+15,x+17,y+6);}g.dispose();}});row.add(visible,BorderLayout.EAST);return row;});
  list.addMouseListener(new java.awt.event.MouseAdapter(){public void mouseClicked(java.awt.event.MouseEvent e){int index=list.locationToIndex(e.getPoint());if(index<0||!list.getCellBounds(index,index).contains(e.getPoint()))return;if(e.getX()>=list.getWidth()-44){int layer=model.get(index).index();work.accept("Mostrar / ocultar capa",()->{DrawingView.nativeSelectLayer(layer);return DrawingView.nativeToggleLayer();});}else if(e.getClickCount()==2)properties();}});JPopupMenu popup=new JPopupMenu();JMenuItem properties=new JMenuItem("Propiedades / mezcla");properties.addActionListener(e->properties());popup.add(properties);list.setComponentPopupMenu(popup);JScrollPane scroll=new JScrollPane(list);scroll.setBorder(BorderFactory.createEmptyBorder());scroll.getViewport().setBackground(getBackground());add(scroll,BorderLayout.CENTER);
  list.addListSelectionListener(e->{if(!syncing&&!e.getValueIsAdjusting()&&list.getSelectedValue()!=null){DrawingView.nativeSelectLayer(list.getSelectedValue().index());changed.run();}});
  JPanel buttons=new JPanel(new GridLayout(1,6,0,0));buttons.setBackground(getBackground());buttons.setBorder(BorderFactory.createEmptyBorder(8,8,8,8));buttons.setPreferredSize(new Dimension(300,64));button(buttons,"new","Añadir capa",DrawingView::nativeAddLayer);button(buttons,"delete","Eliminar capa",DrawingView::nativeDeleteLayer);button(buttons,"duplicate","Duplicar capa",()->DrawingView.nativeLayerAction(0));button(buttons,"merge","Combinar con la inferior",()->DrawingView.nativeLayerAction(1));button(buttons,"up","Subir capa",()->DrawingView.nativeMoveLayer(1));button(buttons,"down","Bajar capa",()->DrawingView.nativeMoveLayer(-1));add(buttons,BorderLayout.SOUTH);
 }
 private void button(JPanel panel,String title,String tip,Callable<Boolean> action){JButton b=new JButton(new app.velyntora.windows.app.CommandIcon(title));app.velyntora.windows.app.EditorTheme.flat(b);b.setMargin(new Insets(4,2,4,2));b.setToolTipText(tip);b.getAccessibleContext().setAccessibleName(tip);b.addActionListener(e->work.accept(tip,action));panel.add(b);}
 public void refresh(){long revision=DrawingView.nativeRevision();int active=DrawingView.nativeActiveLayer();if(revision==shownRevision&&active==shownActive)return;syncing=true;try{model.clear();int count=DrawingView.nativeLayerCount();for(int i=count-1;i>=0;i--){int[] data=DrawingView.nativeLayerThumbnail(i);ImageIcon preview=null;if(data!=null&&data.length==48*48){BufferedImage image=new BufferedImage(48,48,2);image.setRGB(0,0,48,48,data,0,48);BufferedImage check=new BufferedImage(48,48,2);Graphics2D g=check.createGraphics();for(int y=0;y<48;y+=8)for(int x=0;x<48;x+=8){g.setColor(((x/8+y/8)&1)==0?Color.WHITE:Color.LIGHT_GRAY);g.fillRect(x,y,8,8);}g.drawImage(image,0,0,null);g.dispose();preview=new ImageIcon(check.getScaledInstance(48,48,Image.SCALE_SMOOTH));}model.addElement(new Layer(i,DrawingView.nativeLayerName(i)+(DrawingView.nativeTextStyle(i)!=null?" (texto)":DrawingView.nativeLayerIsImage(i)?" ◇":""),DrawingView.nativeLayerVisible(i),preview));}list.setSelectedIndex(count-1-active);shownRevision=revision;shownActive=active;}finally{syncing=false;}}
 public void properties(){int i=DrawingView.nativeActiveLayer();JTextField name=new JTextField(DrawingView.nativeLayerName(i));JCheckBox visible=new JCheckBox("Visible",DrawingView.nativeLayerVisible(i));JSlider opacity=new JSlider(0,100,Math.round(DrawingView.nativeIndexedLayerOpacity(i)*100));String[] modes={"Normal","Multiplicar","Subexponer el color","Sobreexponer el color","Superponer","Diferencia","Aclarar","Oscurecer","Trama","O exclusivo","Luz fuerte","Luz suave","Color","Luminosidad","Tono","Saturación"};JComboBox<String> blend=new JComboBox<>(modes);blend.setSelectedIndex(Math.min(modes.length-1,DrawingView.nativeLayerBlendMode(i)));JPanel form=new JPanel(new GridLayout(0,1));form.add(name);form.add(visible);form.add(new JLabel("Opacidad"));form.add(opacity);form.add(blend);if(JOptionPane.showConfirmDialog(this,form,"Propiedades",JOptionPane.OK_CANCEL_OPTION)==JOptionPane.OK_OPTION){String title=name.getText();boolean show=visible.isSelected();float alpha=opacity.getValue()/100f;int mode=blend.getSelectedIndex();work.accept("Propiedades de capa",()->DrawingView.nativeLayerProperties(i,title,show,alpha,mode));}}
}
